import { loadFont } from "@remotion/google-fonts/InterTight";
import React from "react";
import { AbsoluteFill, Easing, interpolate, spring, useCurrentFrame } from "remotion";

// Ar Studio (03/11) · motion do "Método Abdome Full HD" (nutricionista Ailton Santos, MP), a partir do PDF da VSL.
// Sem fotos nem vídeos: jeito motion. Identidade do próprio PDF: fundo quase preto, verde-limão, branco, grotesca bold.
// Fio: os cantos de foco (visor "em alta definição") que aparecem no 8, no cabide, no nome do método e fecham no "definição".
// Tempos = (arquivo do cliente) (edit/transcripts/voz-v1.json menos os cortes de silêncio).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const AB_FPS = 30;
const END = 49.0;
export const AB_FRAMES = Math.round(END * AB_FPS);

const BG = "#0D0E10";
const LIME = "#C8F23A";
const INK = "#0D0E10";
const GREY = "#9AA0A8";
const PANEL = "#17191D";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const sp = (t: number, a: number, damping = 18, stiffness = 120) =>
  t < a ? 0 : spring({ frame: (t - a) * AB_FPS, fps: AB_FPS, config: { damping, stiffness } });

// texto que sobe da linha e fica parado; `out` faz sair inteiro (para a frase seguinte ocupar o mesmo lugar)
const Rise: React.FC<{ t: number; at: number; size: number; color?: string; weight?: number; out?: number; ls?: string; children: React.ReactNode }> = ({ t, at, size, color = "#FFFFFF", weight = 800, out, ls = "-0.03em", children }) => {
  const e = sp(t, at, 20, 140);
  const o = out === undefined ? 0 : k(t, out, 0.22, Easing.in(Easing.cubic));
  return (
    // máscara com folga em cima (acentos de maiúscula: É, Á, Ã), embaixo (Ç) e dos lados; a margem negativa devolve o espaço
    <div style={{ overflow: "hidden", padding: `${size * 0.24}px ${size * 0.08}px ${size * 0.16}px`, margin: `${-size * 0.24}px ${-size * 0.08}px ${-size * 0.1}px` }}>
      <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.04, letterSpacing: ls, color, whiteSpace: "nowrap", textAlign: "center", transform: `translateY(${((1 - e) * 145 - o * 145).toFixed(1)}%)` }}>{children}</div>
    </div>
  );
};

// cantos de foco: entram abertos e fecham no alvo
const Brackets: React.FC<{ t: number; at: number; w: number; h: number; color?: string; len?: number }> = ({ t, at, w, h, color = LIME, len = 70 }) => {
  const e = sp(t, at, 16, 150);
  const gap = (1 - e) * 90;
  const s: React.CSSProperties = { position: "absolute", width: len, height: len, borderColor: color, borderStyle: "solid", borderWidth: 0, opacity: Math.min(1, e * 2) };
  const b = 8;
  return (
    <div style={{ position: "absolute", left: "50%", top: "50%", width: w, height: h, marginLeft: -w / 2, marginTop: -h / 2, pointerEvents: "none" }}>
      <div style={{ ...s, left: -gap, top: -gap, borderLeftWidth: b, borderTopWidth: b, borderTopLeftRadius: 14 }} />
      <div style={{ ...s, right: -gap, top: -gap, borderRightWidth: b, borderTopWidth: b, borderTopRightRadius: 14 }} />
      <div style={{ ...s, left: -gap, bottom: -gap, borderLeftWidth: b, borderBottomWidth: b, borderBottomLeftRadius: 14 }} />
      <div style={{ ...s, right: -gap, bottom: -gap, borderRightWidth: b, borderBottomWidth: b, borderBottomRightRadius: 14 }} />
    </div>
  );
};

const Ico: React.FC<{ d: string[]; size: number; color?: string; sw?: number }> = ({ d, size, color = LIME, sw = 1.8 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round">
    {d.map((p, i) => <path key={i} d={p} />)}
  </svg>
);
const I_EXAME = ["M9 3h6v3H9z", "M9 4.5H6a1.5 1.5 0 0 0-1.5 1.5v14A1.5 1.5 0 0 0 6 21.5h12a1.5 1.5 0 0 0 1.5-1.5V6A1.5 1.5 0 0 0 18 4.5h-3", "M7.5 14h2l1.5-3 2 6 1.5-3h2"];
const I_PLANO = ["M4 5.5h16v15H4z", "M4 9.5h16", "M8.5 3.5v4", "M15.5 3.5v4", "M8 14l2 2 4-4"];
const I_AJUSTE = ["M4 7h9", "M17 7h3", "M4 17h3", "M11 17h9", "M15 4.5v5", "M9 14.5v5"];

// cabide com a roupa da ceia (desenho simples, sem pessoa)
const Cabide: React.FC<{ w: number; color?: string; fill?: string }> = ({ w, color = "#FFFFFF", fill = LIME }) => (
  <svg width={w} height={w * 1.25} viewBox="0 0 200 250" fill="none">
    <path d="M100 38c0-12 14-12 14-24a14 14 0 0 0-28 0" stroke={color} strokeWidth={6} strokeLinecap="round" />
    <path d="M100 38 L22 82 L178 82 Z" stroke={color} strokeWidth={6} strokeLinejoin="round" />
    <path d="M62 66 L76 82 Q100 100 124 82 L138 66 L150 82 L144 112 Q160 190 176 240 L24 240 Q40 190 56 112 L50 82 Z" fill={fill} />
    <path d="M58 132 Q100 146 142 132" stroke={INK} strokeWidth={5} strokeLinecap="round" opacity={0.35} />
  </svg>
);

// ───────── camadas ─────────
type Enter = "cut" | "push" | "zoom" | "wipe" | "up" | "flood";
type Layer = { a: number; b: number; enter: Enter; bg?: string; ox?: number; oy?: number; M: React.FC<{ t: number; a: number; b: number }> };

const Frame: React.FC<{ t: number; L: Layer; children: React.ReactNode }> = ({ t, L, children }) => {
  const e = L.enter === "cut" ? 1 : k(t, L.a, L.enter === "flood" ? 0.55 : 0.42, IN_OUT);
  let wrap: React.CSSProperties = {};
  let extra = 1;
  if (L.enter === "push") wrap = { transform: `translateX(${((1 - e) * 1080).toFixed(1)}px)` };
  if (L.enter === "up") wrap = { transform: `translateY(${((1 - e) * 1920).toFixed(1)}px)` };
  if (L.enter === "wipe") wrap = { clipPath: `inset(0 0 0 ${((1 - e) * 100).toFixed(2)}%)` };
  if (L.enter === "flood") wrap = { clipPath: `circle(${(e * 160).toFixed(1)}% at ${L.ox ?? 50}% ${L.oy ?? 50}%)` };
  if (L.enter === "zoom") {
    extra = 1 + 0.22 * (1 - e);
    wrap = { opacity: Math.min(1, e * 2), filter: e < 1 ? `blur(${((1 - e) * 14).toFixed(1)}px)` : undefined };
  }
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: L.bg ?? BG, ...wrap }}>
      <AbsoluteFill style={{ transform: `scale(${extra.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// câmera: toda cena já entra se mexendo
const Cam: React.FC<{ t: number; a: number; b: number; from?: number; to?: number; dx?: number; children: React.ReactNode }> = ({ t, a, b, from = 1.0, to = 1.06, dx = 0, children }) => {
  const u = interpolate(t, [a - 0.2, b + 0.4], [0, 1], cl);
  return (
    <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", transform: `scale(${(from + (to - from) * u).toFixed(4)}) translateX(${(dx * (u - 0.5)).toFixed(1)}px)` }}>
      {children}
    </AbsoluteFill>
  );
};

const Col: React.FC<{ gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ gap = 0, children, style }) => (
  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);

// ── 1 · gancho: menos de 8 semanas pro Natal ──
const SceneSemanas: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.08} to={1.0}>
    <Col>
      <Rise t={t} at={0.12} size={72} weight={700}>FALTAM MENOS DE</Rise>
      <div style={{ position: "relative", margin: "10px 0 0" }}>
        <div style={{ transform: `scale(${(0.5 + 0.5 * sp(t, 1.35, 13, 170)).toFixed(3)})`, opacity: Math.min(1, sp(t, 1.35) * 3) }}>
          <div style={{ fontFamily: F, fontWeight: 900, fontSize: 470, lineHeight: 0.9, color: LIME, letterSpacing: "-0.05em" }}>8</div>
        </div>
        <Brackets t={t} at={1.45} w={360} h={440} />
      </div>
      <div style={{ marginTop: 40 }}><Rise t={t} at={1.5} size={150} weight={900}>SEMANAS</Rise></div>
      <Rise t={t} at={2.25} size={96} weight={700} color={GREY}>PRO NATAL</Rise>
      <div style={{ marginTop: 60, display: "flex", gap: 16 }}>
        {Array.from({ length: 8 }).map((_, i) => {
          const e = sp(t, 0.3 + i * 0.07, 14, 180);
          const on = k(t, 2.35 + i * 0.08, 0.2);
          return (
            <div key={i} style={{ width: 82, height: 82, borderRadius: 18, border: `4px solid ${LIME}`, background: `rgba(200,242,58,${(on * (i === 7 ? 1 : 0.22)).toFixed(3)})`, transform: `scale(${e.toFixed(3)})` }} />
          );
        })}
      </div>
    </Col>
  </Cam>
);

// ── 2 · a roupa da ceia já tá separada? ──
const SceneCabide: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const e = sp(t, a, 9, 90);
  return (
    <Cam t={t} a={a} b={b} from={1.0} to={1.07}>
      <Col>
        <div style={{ position: "relative" }}>
          <div style={{ transformOrigin: "50% 4%", transform: `translateY(${((1 - Math.min(1, e)) * -500).toFixed(1)}px) rotate(${((1 - e) * 14).toFixed(2)}deg)` }}>
            <Cabide w={520} />
          </div>
          <Brackets t={t} at={a + 0.35} w={600} h={720} />
        </div>
        <div style={{ marginTop: 90 }}>
          <Rise t={t} at={3.45} size={92} weight={800}>A ROUPA DA CEIA</Rise>
          <Rise t={t} at={4.3} size={92} weight={900} color={LIME}>JÁ TÁ SEPARADA?</Rise>
        </div>
      </Col>
    </Cam>
  );
};

// ── 3 · todo ano é igual ──
const SceneAnos: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.0} to={1.05} dx={-40}>
    <Col>
      <Rise t={t} at={5.4} size={120} weight={900}>TODO ANO</Rise>
      <Rise t={t} at={5.75} size={120} weight={900} color={LIME}>É IGUAL</Rise>
      <div style={{ marginTop: 80, display: "flex", gap: 30 }}>
        {["2023", "2024", "2025"].map((y, i) => {
          const e = sp(t, 5.95 + i * 0.16, 15, 160);
          return (
            <div key={y} style={{ width: 250, height: 380, borderRadius: 30, background: PANEL, border: "2px solid rgba(255,255,255,0.08)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 26, transform: `translateY(${((1 - e) * 160).toFixed(1)}px)`, opacity: Math.min(1, e * 2) }}>
              <Cabide w={150} fill="rgba(200,242,58,0.85)" />
              <div style={{ fontFamily: F, fontWeight: 800, fontSize: 52, color: GREY, letterSpacing: "0.02em" }}>{y}</div>
            </div>
          );
        })}
      </div>
      <div style={{ marginTop: 90, height: 230, display: "flex", alignItems: "center", justifyContent: "center", position: "relative", width: 900 }}>
        <div style={{ position: "absolute" }}>
          <Rise t={t} at={6.84} size={88} weight={700} out={8.45}>ESCOLHE A ROUPA…</Rise>
        </div>
        <div style={{ position: "absolute" }}>
          <Col>
            <Rise t={t} at={8.71} size={88} weight={700}>…E TORCE</Rise>
            <Rise t={t} at={9.15} size={88} weight={900} color={LIME}>PRA SERVIR</Rise>
          </Col>
        </div>
      </div>
    </Col>
  </Cam>
);

// ── 4 · não é falta de força de vontade (fundo limão) ──
const SceneVontade: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => (
  <Cam t={t} a={a} b={b} from={1.0} to={1.08}>
    <Col>
      <Rise t={t} at={10.57} size={100} weight={800} color={INK}>SÓ QUE</Rise>
      <div style={{ height: 30 }} />
      <Rise t={t} at={10.85} size={132} weight={900} color={INK}>NÃO É FALTA</Rise>
      <Rise t={t} at={11.6} size={132} weight={900} color={INK}>DE FORÇA</Rise>
      <Rise t={t} at={12.0} size={132} weight={900} color={INK}>DE VONTADE</Rise>
    </Col>
  </Cam>
);

// ── 5 · músculo por década + dieta que só corta caloria ──
const DEC = [
  { l: "30 ANOS", h1: 600, h2: 600, at: 14.2 },
  { l: "40 ANOS", h1: 545, h2: 470, at: 14.35 },
  { l: "50 ANOS", h1: 490, h2: 360, at: 14.5 },
];
const SceneMusculo: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const drop1 = k(t, 15.5, 0.9, IN_OUT);
  const drop2 = k(t, 21.05, 0.8, IN_OUT);
  return (
    <Cam t={t} a={a} b={b} from={1.0} to={1.06}>
      <Col>
        <div style={{ height: 270, width: 900, position: "relative", display: "flex", justifyContent: "center" }}>
          <div style={{ position: "absolute", top: 0 }}>
            <Col>
              <Rise t={t} at={13.09} size={120} weight={900} out={18.1}>DEPOIS DOS 30</Rise>
              <Rise t={t} at={14.2} size={72} weight={700} color={GREY} out={18.1}>MÚSCULO POR DÉCADA</Rise>
            </Col>
          </div>
          <div style={{ position: "absolute", top: 0 }}>
            <Col>
              <Rise t={t} at={18.45} size={96} weight={900}>DIETA QUE SÓ</Rise>
              <Rise t={t} at={19.45} size={96} weight={900} color={LIME}>CORTA CALORIA</Rise>
            </Col>
          </div>
        </div>
        <div style={{ marginTop: 60, height: 640, display: "flex", gap: 70, alignItems: "flex-end" }}>
          {DEC.map((d, i) => {
            const g = sp(t, d.at, 20, 110);
            const h0 = 600;
            const h = (h0 + (d.h1 - h0) * drop1 + (d.h2 - d.h1) * drop2) * g;
            const lost = Math.max(0, h0 * g - h);
            return (
              <div key={i} style={{ width: 200, height: 600 * g, position: "relative" }}>
                {lost > 1 && <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: lost, borderRadius: "24px 24px 0 0", border: `4px dashed rgba(154,160,168,0.6)`, borderBottom: "none" }} />}
                <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: h, borderRadius: 24, background: i === 0 ? "#FFFFFF" : `rgba(255,255,255,${(0.9 - i * 0.12).toFixed(2)})` }} />
              </div>
            );
          })}
        </div>
        <div style={{ marginTop: 26, display: "flex", gap: 70 }}>
          {DEC.map((d, i) => (
            <div key={i} style={{ width: 200, textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 40, color: GREY, opacity: k(t, d.at + 0.2, 0.4) }}>{d.l}</div>
          ))}
        </div>
        <div style={{ marginTop: 60, height: 120, position: "relative", width: 900, display: "flex", justifyContent: "center" }}>
          {(() => {
            const e1 = sp(t, 15.95, 14, 170) * (1 - k(t, 18.1, 0.2));
            const e2 = sp(t, 21.05, 14, 170);
            const pill = (txt: string, e: number) => (
              <div style={{ position: "absolute", background: LIME, borderRadius: 999, padding: "20px 50px", fontFamily: F, fontWeight: 900, fontSize: 64, color: INK, whiteSpace: "nowrap", transform: `scale(${e.toFixed(3)})`, opacity: Math.min(1, e * 2) }}>{txt}</div>
            );
            return (
              <>
                {pill("−3 A 8% POR DÉCADA", e1)}
                {pill("PERDE AINDA MAIS", e2)}
              </>
            );
          })()}
        </div>
        <div style={{ marginTop: 40, fontFamily: F, fontWeight: 500, fontSize: 30, color: GREY, opacity: k(t, 16.2, 0.5) * (1 - k(t, 18.1, 0.2)) }}>Fonte: Volpi et al., 2004</div>
      </Col>
    </Cam>
  );
};

// ── 6 · o problema não é você. é o plano ──
const SceneProblema: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const p = sp(t, 24.49, 13, 170);
  return (
    <Cam t={t} a={a} b={b} from={1.0} to={1.07}>
      <div style={{ position: "relative", width: 900, height: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ position: "absolute" }}>
          <Col>
            <Rise t={t} at={22.62} size={130} weight={800} out={24.2}>O PROBLEMA</Rise>
            <Rise t={t} at={23.3} size={130} weight={900} out={24.2}>NÃO É VOCÊ.</Rise>
          </Col>
        </div>
        <div style={{ position: "absolute" }}>
          <Col>
            <Rise t={t} at={24.45} size={130} weight={800}>É O</Rise>
            <div style={{ transform: `scale(${(0.7 + 0.3 * p).toFixed(3)})`, opacity: Math.min(1, p * 2) }}>
              <div style={{ fontFamily: F, fontWeight: 900, fontSize: 250, lineHeight: 1, color: LIME, letterSpacing: "-0.04em" }}>PLANO.</div>
