};

// ── 7 · Ailton Santos e o método ──
const SceneMetodo: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const line = k(t, 26.9, 0.6);
  return (
    <Cam t={t} a={a} b={b} from={1.05} to={1.0}>
      <Col>
        <Rise t={t} at={26.0} size={56} weight={600} color={GREY} ls="0.12em">NUTRICIONISTA</Rise>
        <Rise t={t} at={26.7} size={102} weight={800}>AILTON SANTOS</Rise>
        <div style={{ width: 760 * line, height: 3, background: "rgba(255,255,255,0.15)", margin: "70px 0" }} />
        <div style={{ position: "relative", padding: "40px 60px" }}>
          <Col>
            <Rise t={t} at={27.55} size={130} weight={800} ls="-0.035em">Método</Rise>
            <Rise t={t} at={28.55} size={190} weight={900} color={LIME} ls="-0.045em">Abdome</Rise>
            <Rise t={t} at={29.3} size={190} weight={900} color={LIME} ls="-0.045em">Full HD</Rise>
          </Col>
          <Brackets t={t} at={29.8} w={820} h={640} />
        </div>
      </Col>
    </Cam>
  );
};

// ── 8 · as três etapas ──
const STEPS = [
  { n: "01", ico: I_EXAME, title: "EXAMES", size: 160, sub: "Nada de chute.", at: 30.54, subAt: 32.4 },
  { n: "02", ico: I_PLANO, title: "PLANO", size: 160, sub: "que cabe na sua rotina", at: 33.74, subAt: 34.6 },
  { n: "03", ico: I_AJUSTE, title: "ACOMPANHAMENTO", size: 80, sub: "de perto", at: 36.81, subAt: 38.55 },
];
const SceneEtapas: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const pos = STEPS.reduce((acc, s, i) => (i === 0 ? acc : acc + sp(t, s.at - 0.15, 22, 110)), 0);
  // barra do passo: borda da frente anda antes da de trás
  const front = STEPS.reduce((acc, s, i) => (i === 0 ? acc : acc + sp(t, s.at - 0.2, 20, 170)), 0);
  const back = pos;
  const DOT = 300;
  const z = 1 + 0.04 * interpolate(t, [a, b], [0, 1], cl);
  return (
    <AbsoluteFill style={{ alignItems: "center" }}>
      <div style={{ position: "absolute", top: 330, width: 2 * DOT + 90, height: 90 }}>
        <div style={{ position: "absolute", left: 45, right: 45, top: 43, height: 4, background: "rgba(255,255,255,0.12)" }} />
        <div style={{ position: "absolute", left: 45 + back * DOT - 40, width: (front - back) * DOT + 80, top: 25, height: 40, borderRadius: 20, background: LIME }} />
        {STEPS.map((s, i) => {
          const on = i <= Math.round(front);
          return (
            <div key={i} style={{ position: "absolute", left: i * DOT, top: 0, width: 90, height: 90, borderRadius: 45, background: on ? LIME : PANEL, border: `3px solid ${on ? LIME : "rgba(255,255,255,0.2)"}`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 900, fontSize: 36, color: on ? INK : GREY, transform: `scale(${sp(t, a + 0.1 + i * 0.08, 14, 170).toFixed(3)})` }}>{i + 1}</div>
          );
        })}
      </div>
      <AbsoluteFill style={{ transform: `translateX(${(-pos * 1080).toFixed(1)}px) scale(${z.toFixed(4)})` }}>
        {STEPS.map((s, i) => {
          const ic = sp(t, s.at - 0.1, 13, 170);
          return (
            <div key={i} style={{ position: "absolute", left: i * 1080, top: 0, width: 1080, height: 1920, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Col style={{ marginTop: 160 }}>
                <div style={{ width: 230, height: 230, borderRadius: 56, background: "rgba(200,242,58,0.1)", border: "3px solid rgba(200,242,58,0.35)", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${ic.toFixed(3)})` }}>
                  <Ico d={s.ico} size={140} />
                </div>
                <div style={{ marginTop: 60 }}><Rise t={t} at={s.at} size={110} weight={900} color={LIME}>{s.n}</Rise></div>
                <Rise t={t} at={s.at + 0.25} size={s.size} weight={900}>{s.title}</Rise>
                <div style={{ marginTop: 20 }}><Rise t={t} at={s.subAt} size={74} weight={600} color={GREY} ls="-0.02em">{s.sub}</Rise></div>
              </Col>
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ── 9 · em alta definição (desfocado → nítido) ──
