export const AbdomeFullHd: React.FC = () => {
  const t = useCurrentFrame() / AB_FPS;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {LAYERS.map((L, i) => {
        const next = LAYERS[i + 1];
        if (t < L.a || (next && t > next.a + 0.7)) return null;
        return (
          <Frame key={i} t={t} L={L}>
            <L.M t={t} a={L.a} b={L.b} />
          </Frame>
        );
      })}
    </AbsoluteFill>
  );
};

